-- Generated by dbt/scripts/generate_governed_models.py from the governed T-SQL; do not edit by hand.
-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  b.category,
  b.retail_year,
  b.period,
  b.sales_lines,
  b.units_sold,
  b.gross_sales,
  b.discount_value,
  b.sales_revenue,
  b.returns_value,
  b.net_revenue,
  b.cogs,
  b.gross_margin,
  b.promo_sales_revenue,
  CAST(b.sales_revenue AS DOUBLE) / NULLIF(CAST(b.units_sold AS DOUBLE), 0) AS asp,
  CAST(b.gross_margin AS DOUBLE) / NULLIF(CAST(b.net_revenue AS DOUBLE), 0) AS gross_margin_pct,
  CAST(b.returns_value AS DOUBLE) / NULLIF(CAST(b.sales_revenue AS DOUBLE), 0) AS return_rate_value,
  CAST(b.promo_sales_revenue AS DOUBLE) / NULLIF(CAST(b.sales_revenue AS DOUBLE), 0) AS promo_revenue_share,
  p.net_revenue AS net_revenue_py,
  100.0 * (
    CAST(b.net_revenue AS DOUBLE) / NULLIF(CAST(p.net_revenue AS DOUBLE), 0) - 1
  ) AS net_revenue_yoy_pct
FROM (
  SELECT
    x.category,
    x.retail_year,
    x.period,
    SUM(x.sales_lines) AS sales_lines,
    SUM(x.units_sold) AS units_sold,
    SUM(x.gross_sales) AS gross_sales,
    SUM(x.discount_value) AS discount_value,
    SUM(x.sales_revenue) AS sales_revenue,
    SUM(x.returns_value) AS returns_value,
    SUM(x.net_revenue) AS net_revenue,
    SUM(x.cogs) AS cogs,
    SUM(x.gross_margin) AS gross_margin,
    SUM(x.promo_sales_revenue) AS promo_sales_revenue
  FROM (
    SELECT
      category,
      retail_year,
      retail_half AS period,
      sales_lines,
      units_sold,
      gross_sales,
      discount_value,
      sales_revenue,
      returns_value,
      net_revenue,
      cogs,
      gross_margin,
      promo_sales_revenue
    FROM {{ ref('v_performance_category_week') }}
    UNION ALL
    SELECT
      category,
      retail_year,
      N'FY',
      sales_lines,
      units_sold,
      gross_sales,
      discount_value,
      sales_revenue,
      returns_value,
      net_revenue,
      cogs,
      gross_margin,
      promo_sales_revenue
    FROM {{ ref('v_performance_category_week') }}
  ) AS x
  GROUP BY
    x.category,
    x.retail_year,
    x.period
) AS b
LEFT JOIN (
  SELECT
    category,
    retail_year,
    retail_half AS period,
    SUM(net_revenue) AS net_revenue
  FROM {{ ref('v_performance_category_week') }}
  GROUP BY
    category,
    retail_year,
    retail_half
  UNION ALL
  SELECT
    category,
    retail_year,
    N'FY',
    SUM(net_revenue)
  FROM {{ ref('v_performance_category_week') }}
  GROUP BY
    category,
    retail_year
) AS p
  ON p.category = b.category
  AND p.period = b.period
  AND p.retail_year = b.retail_year - 1
